<?php $case=$case??[];$ownerUrl=$this->url('/mentor/profile?id='.$experience['mentor_id'].'&experience_id='.$experience['id']);$sections=[];foreach(\Morshed\Product\ExperienceCases::NARRATIVE as $key=>$label){if(trim($case[$key]??'')!==''){$sections[$key]=$label;}}$text=$case?implode(' ',array_map(fn($k)=>(string)($case[$k]??''),array_keys($sections))):$experience['body'];$minutes=max(1,(int)ceil(preg_match_all('/\S+/u',$text)/180)); ?>
