<div class="reading-layout"><div class="reading-main"><?php if(!$case): ?><section class="reading-section reading-copy"><?= $this->paragraphs($experience['body']) ?></section><?php else: ?><?php $n=0;foreach($sections as $key=>$label): $n++; ?><section class="reading-section <?= in_array($key,['results','lessons'],true)?'reading-highlight':'' ?>" id="reading-<?= $key ?>"><div class="reading-section-heading"><span><?= str_pad((string)$n,2,'0',STR_PAD_LEFT) ?></span><h2><?= $label ?></h2></div><div class="reading-copy"><?= $this->paragraphs($case[$key]) ?></div></section><?php endforeach; ?><?php endif; ?>
